def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return max(0, min(budget, base))

    prev_bids = []
    distressed_count = 0
    rich_aggressive = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 2:
            distressed_count += 1
        if opp.get('budget', 0) > budget and opp.get('daily_salary', 0) >= DAILY_SALARY:
            rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 2 or no_water_days >= 2:
        bid = DAILY_SALARY * 0.95
    elif no_water_days >= 1:
        bid = DAILY_SALARY * 0.78
    else:
        if supply >= 22:
            bid = DAILY_SALARY * 0.38
        elif supply >= 19:
            bid = DAILY_SALARY * 0.5
        else:
            bid = DAILY_SALARY * 0.62

        if highest_prev >= DAILY_SALARY * 0.9:
            bid = min(bid, DAILY_SALARY * 0.42) if hp >= 4 else max(bid, DAILY_SALARY * 0.88)
        elif highest_prev >= DAILY_SALARY * 0.7:
            bid = max(bid, min(DAILY_SALARY * 0.72, highest_prev + 1.0))
        elif highest_prev > 0:
            bid = max(bid, min(DAILY_SALARY * 0.6, avg_prev + 1.5))

        if distressed_count >= 2 and hp >= 4:
            bid *= 0.9
        if rich_aggressive >= 2 and supply < 18 and hp <= 4:
            bid = max(bid, DAILY_SALARY * 0.82)

    if budget < DAILY_SALARY * 0.6:
        if hp >= 4 and no_water_days == 0:
            bid = min(bid, budget * 0.55)
        else:
            bid = min(bid, max(budget * 0.75, 1))

    return max(0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents, bid conservatively.
    if not alive_opponents:
        return max(0.0, min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday's bids from immediate previous_trace.
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Baseline target bid depends on how much water likely exists.
    # If supply is tight, we must bid more to secure water.
    # supply range is [15,25].
    if supply <= 16.0:
        pressure_supply = 1.0
    elif supply <= 19.0:
        pressure_supply = 0.8
    elif supply <= 22.0:
        pressure_supply = 0.6
    else:
        pressure_supply = 0.45

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Determine opponent pressure from yesterday.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        lowest_prev_bid = min(yesterday_bids)

        # If someone was bidding aggressively, match just below to win without overpaying.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp > 3.0:
                target = DAILY_SALARY * 0.28 + (highest_prev_bid - DAILY_SALARY * 0.85) * 0.15
                target = min(target, highest_prev_bid - 1.0)
            else:
                target = DAILY_SALARY * 0.75
                target = min(target, highest_prev_bid - 0.5)
        # If bids were moderate, bid enough to be competitive.
        elif highest_prev_bid >= DAILY_SALARY * 0.55:
            target = max(highest_prev_bid * 0.92, lowest_prev_bid + 1.0)
        else:
            # Low bids: bid slightly above the likely clearing price.
            target = max(DAILY_SALARY * 0.45 * pressure_supply, lowest_prev_bid + 1.5)
    else:
        # No trace info: use supply pressure and our hp.
        if my_hp <= 2.0:
            target = DAILY_SALARY * 0.85
        elif my_hp <= 3.0:
            target = DAILY_SALARY * 0.65
        else:
            target = DAILY_SALARY * 0.5 * pressure_supply

    # Convert target into a bid amount; ensure we don't exceed budget.
    # Also cap at a reasonable fraction of budget to avoid going broke.
    max_reasonable = my_budget * 0.95
    bid = max(0.0, min(target, max_reasonable))

    # If supply is very low, increase bid to secure at least one WATER_REQ unit.
    # (We don't know exact allocation rule; this biases toward winning.)
    if supply < float(WATER_REQ) * 2.0:
        bid = min(max_reasonable, bid + DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    bid = DAILY_SALARY * 0.4

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.9
        if day_context['day'] >= EPISODE_DAYS - 2:
            bid = DAILY_SALARY * 0.95

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    total_opponent_water_req = sum(o['water_requirement'] for o in alive_opponents)
    total_demand = WATER_REQ + total_opponent_water_req
    current_supply = day_context['supply']

    if current_supply < total_demand:
        if highest_prev_bid > DAILY_SALARY * 0.6:
            bid = max(bid, highest_prev_bid + 5)

        scarcity_ratio = total_demand / current_supply
        if scarcity_ratio > 1.5:
            bid = max(bid, DAILY_SALARY * 0.8)
        elif scarcity_ratio > 1.1:
            bid = max(bid, DAILY_SALARY * 0.65)

    else:
        if my_status['hp'] > 2 and my_status['no_water_days'] == 0:
            bid = min(bid, DAILY_SALARY * 0.3)
        if highest_prev_bid > DAILY_SALARY * 0.5:
            bid = max(bid, DAILY_SALARY * 0.4)

    bid = min(bid, my_status['budget'])
    bid = max(bid, 0.0)

    return bid
